"use client";

import { useEffect, useMemo, useState } from "react";
import dynamic from "next/dynamic";
import Link from "next/link";
import { AlertCircle, Heart, Loader2, MapPin, MapPinned } from "lucide-react";
import { authRequest } from "@/lib/auth-client";
import { cn } from "@/lib/cn";
import { useAuth } from "@/providers/AuthProvider";
import { useToast } from "@/components/ui/ToastProvider";
import type { MapPoint } from "@/features/couple/MapView";

// Bản đồ render hoàn toàn phía client (leaflet đụng tới window/document) → tắt SSR.
const MapView = dynamic(() => import("@/features/couple/MapView"), {
  ssr: false,
  loading: () => (
    <div className="grid h-full w-full place-items-center bg-[var(--ui-bg-deep)] text-[color:var(--ui-text-muted)]">
      <span className="flex items-center gap-2 text-sm">
        <Loader2 size={16} className="animate-spin" /> Đang dựng bản đồ...
      </span>
    </div>
  )
});

type RoomLite = { id: string; roomName: string } | null;

type MemoryLite = {
  id: string;
  title: string;
  memoryDate: string | null;
  placeName: string | null;
  latitude: number | string | null;
  longitude: number | string | null;
};

const panelClass = "ui-section text-white";

function formatDate(value: string | null) {
  if (!value) {
    return null;
  }

  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return null;
  }

  return date.toLocaleDateString("vi-VN", { day: "2-digit", month: "2-digit", year: "numeric" });
}

export function CoupleMapPage() {
  const { isGuest, openAuth } = useAuth();
  const { notify } = useToast();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [room, setRoom] = useState<RoomLite>(null);
  const [memories, setMemories] = useState<MemoryLite[]>([]);
  const [focus, setFocus] = useState<{ lat: number; lng: number; token: number } | null>(null);

  async function load() {
    if (isGuest) {
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(null);
    try {
      const nextRoom = await authRequest<RoomLite>("/room");
      setRoom(nextRoom);

      if (!nextRoom) {
        return;
      }

      const memoryData = await authRequest<MemoryLite[]>("/memories");
      setMemories(memoryData);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Không tải được dữ liệu bản đồ.");
      notify({ tone: "error", title: "Không tải được bản đồ", message: "Kiểm tra backend và database giúp mình nhé." });
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- nạp dữ liệu khi mount/đổi trạng thái khách
    void load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isGuest]);

  // Chỉ giữ kỷ niệm có toạ độ hợp lệ (lat/lng có thể là chuỗi DECIMAL từ MySQL → ép số + lọc NaN/0,0).
  const points = useMemo<MapPoint[]>(() => {
    return memories
      .map((memory) => ({
        id: memory.id,
        title: memory.title,
        placeName: memory.placeName,
        dateLabel: formatDate(memory.memoryDate),
        lat: Number(memory.latitude),
        lng: Number(memory.longitude)
      }))
      .filter(
        (point) =>
          Number.isFinite(point.lat) &&
          Number.isFinite(point.lng) &&
          !(point.lat === 0 && point.lng === 0)
      );
  }, [memories]);

  const header = (
    <header className={cn(panelClass, "flex items-center gap-3")}>
      <div className="grid h-11 w-11 shrink-0 place-items-center rounded-[var(--ui-radius-sm)] border border-white/10 bg-[var(--ui-accent-soft)] text-[color:var(--ui-accent)]">
        <MapPinned size={20} />
      </div>
      <div className="min-w-0">
        <h1 className="ui-h2 text-white">Bản đồ kỷ niệm</h1>
        <p className="ui-body mt-0.5 text-[color:var(--ui-text-muted)]">Những nơi hai đứa từng đặt chân tới, ghim lại trên cùng một bầu trời.</p>
      </div>
    </header>
  );

  if (isGuest) {
    return (
      <section className="mx-auto max-w-7xl">
        <div className={panelClass}>
          <h1 className="ui-h1 text-white">Bản đồ chỉ dành cho hai đứa mình</h1>
          <p className="ui-body mt-3 max-w-xl leading-6 text-[color:var(--ui-text-muted)]">
            Đăng nhập và vào phòng riêng để ghim những địa điểm hai người từng đi qua lên bản đồ.
          </p>
          <button type="button" onClick={openAuth} className="only-button-primary mt-5">
            Đăng nhập / Đăng ký
          </button>
        </div>
      </section>
    );
  }

  if (loading) {
    return (
      <section className="mx-auto max-w-7xl">
        <div className={panelClass}>
          <div className="ui-body flex min-h-52 items-center justify-center gap-3 text-[color:var(--ui-text-muted)]">
            <Loader2 size={18} className="animate-spin" /> Đang mở bản đồ kỷ niệm...
          </div>
        </div>
      </section>
    );
  }

  if (error) {
    return (
      <section className="mx-auto grid max-w-7xl gap-5">
        {header}
        <div className={cn(panelClass, "grid place-items-center text-center")}>
          <div className="grid h-11 w-11 place-items-center rounded-[var(--ui-radius-sm)] bg-[#ff5ea8]/12 text-[#ff9ac7]">
            <AlertCircle size={20} />
          </div>
          <p className="ui-h3 mt-3 text-white">Không tải được bản đồ</p>
          <p className="ui-body mx-auto mt-1 max-w-sm leading-6 text-[color:var(--ui-text-muted)]">{error}</p>
          <button type="button" onClick={() => void load()} className="only-button-secondary mt-4">
            Thử lại
          </button>
        </div>
      </section>
    );
  }

  // Chưa ghép đôi (tương đương 428) — backend trả /room = null khi chưa vào phòng.
  if (!room) {
    return (
      <section className="mx-auto grid max-w-7xl gap-5">
        {header}
        <div className={cn(panelClass, "grid place-items-center text-center")}>
          <div className="grid h-11 w-11 place-items-center rounded-[var(--ui-radius-sm)] bg-[var(--ui-accent-soft)] text-[color:var(--ui-accent)]">
            <Heart size={20} fill="currentColor" />
          </div>
          <p className="ui-h3 mt-3 text-white">Chưa ghép đôi</p>
          <p className="ui-body mx-auto mt-1 max-w-sm leading-6 text-[color:var(--ui-text-muted)]">
            Hãy tạo hoặc tham gia một phòng riêng trước, rồi quay lại đây để ghim những địa điểm của hai người.
          </p>
          <Link href="/dashboard" className="only-button-primary mt-4">
            Tới phòng riêng
          </Link>
        </div>
      </section>
    );
  }

  if (points.length === 0) {
    return (
      <section className="mx-auto grid max-w-7xl gap-5">
        {header}
        <div className={cn(panelClass, "grid place-items-center text-center")}>
          <div className="grid h-11 w-11 place-items-center rounded-[var(--ui-radius-sm)] bg-[var(--ui-accent-soft)] text-[color:var(--ui-accent)]">
            <MapPin size={20} />
          </div>
          <p className="ui-h3 mt-3 text-white">Chưa có địa điểm nào</p>
          <p className="ui-body mx-auto mt-1 max-w-md leading-6 text-[color:var(--ui-text-muted)]">
            Khi thêm một kỷ niệm, hãy điền thêm <b className="text-white">địa điểm</b> kèm <b className="text-white">vĩ độ</b> và <b className="text-white">kinh độ</b> — kỷ niệm đó sẽ tự xuất hiện trên bản đồ này.
          </p>
          <Link href="/memories" className="only-button-primary mt-4">
            Thêm kỷ niệm có địa điểm
          </Link>
        </div>
      </section>
    );
  }

  return (
    <section className="mx-auto grid max-w-7xl gap-5">
      {header}

      <div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_320px]">
        <div className="overflow-hidden rounded-[var(--ui-radius-lg)] border border-[var(--ui-border-strong)] bg-[var(--ui-bg-deep)] shadow-[0_14px_36px_rgba(0,0,0,0.22)]">
          <div className="h-[58vh] min-h-[360px] w-full">
            <MapView points={points} focus={focus} />
          </div>
        </div>

        <aside className={cn(panelClass, "flex flex-col gap-3")}>
          <div className="flex items-center justify-between">
            <p className="ui-eyebrow flex items-center gap-1.5">
              <MapPin size={12} /> Địa điểm
            </p>
            <span className="ui-pill">{points.length} nơi</span>
          </div>

          <ul className="grid max-h-[52vh] gap-2 overflow-y-auto pr-1">
            {points.map((point) => (
              <li key={point.id}>
                <button
                  type="button"
                  onClick={() => setFocus({ lat: point.lat, lng: point.lng, token: Date.now() })}
                  className="flex w-full items-start gap-3 rounded-[var(--ui-radius-md)] border border-white/8 bg-white/[0.035] px-3 py-2.5 text-left transition hover:border-[color:var(--ui-accent)]/40 hover:bg-white/[0.06]"
                >
                  <span className="mt-0.5 grid h-8 w-8 shrink-0 place-items-center rounded-full bg-[var(--ui-accent-soft)] text-[color:var(--ui-accent)]">
                    <MapPin size={15} />
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-[13.5px] font-semibold text-white">{point.title}</span>
                    {point.placeName ? (
                      <span className="block truncate text-[12px] text-[color:var(--ui-text-muted)]">{point.placeName}</span>
                    ) : null}
                    {point.dateLabel ? (
                      <span className="block text-[11.5px] text-[color:var(--ui-text-soft)]">{point.dateLabel}</span>
                    ) : null}
                  </span>
                </button>
              </li>
            ))}
          </ul>
        </aside>
      </div>
    </section>
  );
}
